/** void CB2_OpenFlyMap(void) */
export function CB2_OpenFlyMap(): any {
  switch (gMain.state)
      {
      case 0:
          SetVBlankCallback(NULL);
          SetGpuReg(REG_OFFSET_DISPCNT, 0);
          SetGpuReg(REG_OFFSET_BG0HOFS, 0);
          SetGpuReg(REG_OFFSET_BG0VOFS, 0);
          SetGpuReg(REG_OFFSET_BG1HOFS, 0);
          SetGpuReg(REG_OFFSET_BG1VOFS, 0);
          SetGpuReg(REG_OFFSET_BG2VOFS, 0);
          SetGpuReg(REG_OFFSET_BG2HOFS, 0);
          SetGpuReg(REG_OFFSET_BG3HOFS, 0);
          SetGpuReg(REG_OFFSET_BG3VOFS, 0);
          sFlyMap = Alloc(0);
          if (sFlyMap == NULL)
          {
              SetMainCallback2(CB2_ReturnToFieldWithOpenMenu);
          }
          else
          {
              ResetPaletteFade();
              ResetSpriteData();
              FreeSpriteTileRanges();
              FreeAllSpritePalettes();
              gMain.state++;
          }
          break;
      case 1:
          ResetBgsAndClearDma3BusyFlags(0);
          InitBgsFromTemplates(1, sFlyMapBgTemplates, ARRAY_COUNT(sFlyMapBgTemplates));
          gMain.state++;
          break;
      case 2:
          InitWindows(sFlyMapWindowTemplates);
          DeactivateAllTextPrinters();
          gMain.state++;
          break;
      case 3:
          LoadUserWindowBorderGfx(0, _0x65, BG_PLTT_ID(13));
          ClearScheduledBgCopiesToVram();
          gMain.state++;
          break;
      case 4:
          InitRegionMap(sFlyMap.regionMap, FALSE);
          CreateRegionMapCursor(TAG_CURSOR, TAG_CURSOR);
          CreateRegionMapPlayerIcon(TAG_PLAYER_ICON, TAG_PLAYER_ICON);
          sFlyMap.mapSecId = sFlyMap.regionMap.mapSecId;
          StringFill(sFlyMap.nameBuffer, CHAR_SPACE, MAP_NAME_LENGTH);
          sDrawFlyDestTextWindow = TRUE;
          DrawFlyDestTextWindow();
          gMain.state++;
          break;
      case 5:
          LZ77UnCompVram(sRegionMapFrameGfxLZ, BG_CHAR_ADDR(3));
          gMain.state++;
          break;
      case 6:
          LZ77UnCompVram(sRegionMapFrameTilemapLZ, BG_SCREEN_ADDR(30));
          gMain.state++;
          break;
      case 7:
          LoadPalette(sRegionMapFramePal, BG_PLTT_ID(1), 0);
          PutWindowTilemap(WIN_FLY_TO_WHERE);
          FillWindowPixelBuffer(WIN_FLY_TO_WHERE, PIXEL_FILL(0));
          AddTextPrinterParameterized(WIN_FLY_TO_WHERE, FONT_NORMAL, gText_FlyToWhere, 0, 1, 0, NULL);
          ScheduleBgCopyTilemapToVram(0);
          gMain.state++;
          break;
      case 8:
          LoadFlyDestIcons();
          gMain.state++;
          break;
      case 9:
          BlendPalettes(PALETTES_ALL, 16, 0);
          SetVBlankCallback(VBlankCB_FlyMap);
          gMain.state++;
          break;
      case 10:
          SetGpuReg(REG_OFFSET_BLDCNT, 0);
          SetGpuRegBits(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          ShowBg(0);
          ShowBg(1);
          ShowBg(2);
          SetFlyMapCallback(CB_FadeInFlyMap);
          SetMainCallback2(CB2_FlyMap);
          gMain.state++;
          break;
      }
}

